// SigTrans-Dyn - translation mapping demo
var MAP = { "x86:mov": "arm:mov", "x86:add": "arm:add", "x86:jmp": "arm:b" };
function translate(insn) {
  var key = "x86:" + insn.split(" ")[0];
  return (MAP[key] || "arm:??") + insn.slice(insn.indexOf(" "));
}
var prog = ["mov eax, 1", "add eax, 2", "jmp done"];
console.log("Translator: SigTrans-Dyn | any -> host");
prog.forEach(function(i) { console.log("  " + i + "  =>  " + translate(i)); });
console.log("Method: cached dynarec -> PASS");

